package com.careernav.service;
import com.careernav.domain.ApiModels.*;
import org.springframework.stereotype.Service;
import java.util.*;
@Service
public class LearningPathService {
 private final ResumeService resumeService;private final JobService jobService;
 public LearningPathService(ResumeService resumeService,JobService jobService){this.resumeService=resumeService;this.jobService=jobService;}
 public LearningPath generate(Long resumeId,String requestedRole){ResumeView r=resumeService.get(resumeId);String role=requestedRole==null||requestedRole.isBlank()?r.targetRole():requestedRole;Set<String> current=jobService.normalize(r.skills()),target=targetSkills(role);List<String> gaps=target.stream().filter(s->!current.contains(s)).toList();int readiness=target.isEmpty()?0:(int)Math.round((target.size()-gaps.size())*100.0/target.size());List<LearningModule> modules=new ArrayList<>();int i=1;modules.add(new LearningModule(i++,"基础补齐与认知校准","1 周","建立目标岗位知识地图",gaps.stream().limit(2).toList(),"输出岗位技能清单与个人差距表",gaps.isEmpty()?"已掌握":"进行中"));modules.add(new LearningModule(i++,"核心技术专项突破","3-4 周","完成核心技术最小闭环",part(gaps,2,5),"完成一个可运行的核心功能 Demo",gaps.size()>2?"待开始":"可跳过"));modules.add(new LearningModule(i++,"工程化项目实战","2-3 周","把技能转化为可验证的项目证据",List.of("接口设计","测试","性能优化","Docker 部署"),"上线一个可访问项目并记录压测数据","待开始"));modules.add(new LearningModule(i,"面试表达与简历复盘","1 周","形成有数据、有深度的面试叙事",List.of("STAR 表达","项目追问","八股复盘","模拟面试"),"完成 3 次模拟面试并迭代简历","待开始"));String summary=String.format("当前岗位准备度为 %d%%。建议先补齐 %s，再通过工程化项目沉淀证据；每完成一个模块更新简历并重新诊断。",readiness,gaps.isEmpty()?"项目深度与面试表达":String.join("、",gaps.stream().limit(3).toList()));return new LearningPath(r.id(),role,readiness,List.copyOf(current),List.copyOf(target),gaps,modules,summary);}
 private Set<String> targetSkills(String role){String v=role==null?"":role.toLowerCase(Locale.ROOT);if(v.contains("前端")||v.contains("front"))return new LinkedHashSet<>(List.of("html","css","javascript","typescript","vue","react","webpack","浏览器原理"));if(v.contains("算法")||v.contains("ai")||v.contains("人工智能")||v.contains("大模型"))return new LinkedHashSet<>(List.of("python","pytorch","langchain","rag","mcp","prompt engineering","docker"));if(v.contains("测试")||v.contains("qa"))return new LinkedHashSet<>(List.of("java","python","selenium","pytest","接口测试","性能测试","ci/cd"));return new LinkedHashSet<>(List.of("java","spring boot","mysql","redis","spring cloud","message queue","docker","jvm"));}
 private List<String> part(List<String> values,int from,int to){if(values.isEmpty())return List.of("项目架构复盘");return values.subList(Math.min(from,values.size()),Math.min(to,values.size()));}
}
